// Generated by vibelang from worker/github/Config.vibe; the migrate flow writes it again with each batch.
import * as Config from "effect/Config";
import * as Option from "effect/Option";
import * as Redacted from "effect/Redacted";
import * as Schema from "effect/Schema";
import * as Effect from "effect/Effect";
import { repoId } from "../../src/features/repo/contract.js";
import { DEFAULT_REPOSITORY } from "../SignIn.js";
/** GitHub's REST API when `GITHUB_API_URL` is unset. */
export const DEFAULT_API_URL = "https://api.github.com";
const repositoryName = Schema.String.check(Schema.isPattern(/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/));
/** An http(s) URL: a malformed `GITHUB_API_URL` fails the deployment's config, never a step. */
const httpUrl = Schema.String.check(Schema.makeFilter((value) => URL.canParse(value) && /^https?:$/.test(new URL(value).protocol)));
/** `owner/name` as a `Repository`; `repositoryName` has checked its shape. */
export const repositoryOf = (full) => {
    const [owner, name] = full.split("/");
    return { owner, name, id: repoId(owner, name) };
};
/** `GITHUB_REPOSITORY`: the repository G0 syncs, the one sign-in reads roles on. */
export const repository = Config.schema(repositoryName, "GITHUB_REPOSITORY").pipe(Config.withDefault(DEFAULT_REPOSITORY), Config.map(repositoryOf));
/** The same API origin for metadata reads, including when the App is no longer configured. */
export const apiUrl = Config.schema(httpUrl, "GITHUB_API_URL").pipe(Config.withDefault(DEFAULT_API_URL));
/**
 * Reads `GITHUB_APP_ID`, `GITHUB_APP_PRIVATE_KEY`, `GITHUB_WEBHOOK_SECRET`, `GITHUB_REPOSITORY` and `GITHUB_API_URL`.
 * `None` without the ID or the key: the git loop is off. The key's text is never read into a log line.
 */
export const configured = Effect.gen(function* configured() {
    const appId = yield* Config.option(Config.NonEmptyString("GITHUB_APP_ID"));
    const privateKey = yield* Config.option(Config.Redacted("GITHUB_APP_PRIVATE_KEY"));
    const webhookSecret = yield* Config.option(Config.Redacted("GITHUB_WEBHOOK_SECRET"));
    const synced = yield* repository;
    const apiBaseUrl = yield* apiUrl;
    if (Option.isNone(appId) || Option.isNone(privateKey) || Redacted.value(privateKey.value).trim() === "") {
        return Option.none();
    }
    return Option.some({
        appId: appId.value,
        privateKey: privateKey.value,
        webhookSecret: Option.filter(webhookSecret, (secret) => Redacted.value(secret).length > 0),
        repository: synced,
        apiBaseUrl,
    });
});
